@n2 syntax.nominal head="o1 wide"
@k1 syntax.coordination conjunction="and" conjunct=$n1 conjunct=$n3
@n3 syntax.nominal head="flat"

sop:
@n1 syntax.nominal dependent="first" head="component"
@r1 syntax.relation marker="of" from=$n1 to=$n2
@n2 syntax.nominal head="o1"
@n3 syntax.nominal head="delete"
@c1 syntax.clause form=fragment complement=$n1
@r2 syntax.relation from=$n1 to=$n3

alt:
@n1 syntax.nominal dependent="first" head="component"
@r1 syntax.relation marker="of" from=$n1 to=$n2
@n2 syntax.nominal head="o1"
@c1 syntax.clause form=imperative verb="delete"
@c2 syntax.clause form=fragment complement=$n1
@r2 syntax.relation from=$c1 to=$c2
